import {displaySpectralXYZ} from './plt-spectrum.js';
const $=id=>document.getElementById(id),ids=['pltPreset','pltModelYaw','pltScale','pltMaterial','pltYaw','pltPitch','pltWavelength','pltDepth','pltResolution','pltSamples','pltCompute','pltSpectrum','pltSource','pltSourcePower','pltSpectralMaterial'];
let worker=null,generation=0,lastResult=null,lastPreview=null,activeRequest=null,objText=null,objName=null,busy=false;
function status(text){$('pltStatus').textContent=text;}
function stop(){generation++;if(worker){worker.terminate();worker=null;}busy=false;$('pltCancel').hidden=true;$('pltRun').disabled=false;$('pltProgress').hidden=true;}
function clearResult(){lastResult=null;lastPreview=null;activeRequest=null;for(const mode of ['Wave','Ray'])$(`plt${mode}Samples`).textContent='尚未采样';for(const k of ['Wave','Ray']){$(`plt${k}Empty`).hidden=false;const canvas=$(`plt${k}Canvas`);canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);}for(const id of ['pltGeometry','pltEvents','pltMulti','pltParity'])$(id).textContent='—';$('pltBackend').textContent='等待计算';$('pltMeasurement').textContent='相机不是几何预览。旋转相机或模型会改变实际采样、可见性和光传输。';$('pltWarnings').textContent='';$('pltReport').textContent='尚无结果';$('pltDownload').disabled=true;}
function spectralControls(){const visible=$('pltSpectrum').value==='visible';$('pltWavelength').disabled=visible;$('pltSource').disabled=!visible;$('pltSpectralMaterial').disabled=!visible;$('pltSpectralNote').textContent=visible?'360–830 nm 光谱采样 → CIE XYZ → sRGB。64 spp 起步仍可能有彩色噪声；不裁剪路径权重。微型场景宽 240 µm，默认盒体宽 52 µm；毫米级场景的可见光衍射通常更细。表面使用明确的合成反射谱，边缘仍为理想标量 PEC UTD。':'单色默认 0.025 mm = 25 µm，属于红外；灰度显示不是人眼颜色。切换可见光会逐样本重算波长与光束，再累计 CIE XYZ。';}
function invalidate(){stop();spectralControls();clearResult();$('pltYawValue').textContent=`${$('pltYaw').value}°`;$('pltPitchValue').textContent=`${$('pltPitch').value}°`;status('参数已改变。重新计算后，图像会使用新的几何与相机。');}
function request(){const width=Number($('pltResolution').value);return {id:generation,backend:$('pltCompute').value,compare:true,scene:{preset:$('pltPreset').value,objText,modelRotation:[0,Number($('pltModelYaw').value),0],modelScale:Number($('pltScale').value),modelMaterial:Number($('pltMaterial').value),emission:Number($('pltSourcePower').value)},camera:{yaw:Number($('pltYaw').value),pitch:Number($('pltPitch').value)},options:{width,height:Math.round(width*.75),samplesPerPixel:Number($('pltSamples').value),maxDepth:Number($('pltDepth').value),wavelengthMm:Number($('pltWavelength').value),spectralMode:$('pltSpectrum').value,spectralSource:$('pltSource').value,spectralMaterial:$('pltSpectralMaterial').value,seed:7391}};}
function image(result,id){const canvas=$(id),gain=2**Number($('pltExposure').value);canvas.width=result.width;canvas.height=result.height;const ctx=canvas.getContext('2d'),pixels=ctx.createImageData(result.width,result.height);for(let i=0;i<result.image.length;i++){const value=result.image[i];if(!Number.isFinite(value)||value<0)throw new Error('Invalid camera sample');if(result.spectralMode==='visible'){const color=displaySpectralXYZ(result.xyz.subarray(3*i,3*i+3),Number($('pltExposure').value));pixels.data.set([...color.rgb,255],4*i);}else{const mapped=1-Math.exp(-gain*value),s=Math.round(255*mapped**(1/2.2));pixels.data.set([s,s,s,255],4*i);}}ctx.putImageData(pixels,0,0);}
function paint(){const frame=lastResult??lastPreview;if(!frame)return;for(const result of frame.results){image(result,result.wave?'pltWaveCanvas':'pltRayCanvas');$(result.wave?'pltWaveEmpty':'pltRayEmpty').hidden=true;}}
function validateXYZ(result,visible){if(visible){if(result.spectralMode!=='visible'||!(result.xyz instanceof Float64Array||result.xyz instanceof Float32Array)||result.xyz.length!==result.image.length*3||!result.xyz.every(v=>Number.isFinite(v)&&v>=0)||result.image.some((v,i)=>v!==result.xyz[3*i+1]))throw new Error('XYZ 光谱图像缺失、无效或 Y 分量不一致');}else if(result.spectralMode==='visible'||result.xyz)throw new Error('光谱结果与请求模式不符');}
function showPreview(frame){
 const o=activeRequest?.options;
 if(!o||frame?.partial!==true||frame.width!==o.width||frame.height!==o.height||!Array.isArray(frame.results)||frame.results.length!==2||new Set(frame.results.map(r=>r.wave)).size!==2)throw new Error('渐进帧缺失或尺寸不符');
 for(const r of frame.results){
  if(typeof r.wave!=='boolean'||r.width!==o.width||r.height!==o.height||r.image?.length!==o.width*o.height||r.sampleCounts?.length!==r.image.length)throw new Error('渐进采样计数与图像不符');
  validateXYZ(r,o.spectralMode==='visible');
  let min=Infinity,max=0;for(let i=0;i<r.image.length;i++){const n=r.sampleCounts[i],v=r.image[i];if(!Number.isInteger(n)||n<0||n>o.samplesPerPixel||!Number.isFinite(v)||v<0||(n===0&&v!==0))throw new Error('渐进帧含无效数值');min=Math.min(min,n);max=Math.max(max,n);}
  if(r.completedSamplesPerPixel!==min||r.minSamplesPerPixel!==min||r.maxSamplesPerPixel!==max)throw new Error('渐进采样进度不一致');
  $(r.wave?'pltWaveSamples':'pltRaySamples').textContent=`${min===max?min:`${min}–${max}`} / ${o.samplesPerPixel} spp · 未完成`;
 }
 const completed=Math.min(...frame.results.map(r=>r.completedSamplesPerPixel));if(frame.completedSamplesPerPixel!==completed)throw new Error('完整采样轮数不一致');
 lastPreview=frame;paint();$('pltBackend').textContent='分块渐进计算';$('pltMeasurement').textContent=`两幅图均已完成 ${completed} 轮全画幅采样，目标 ${o.samplesPerPixel} 轮。分块预览只显示已计算并核验或采用 CPU 参考的结果；尚未采样处为黑色。`;
 $('pltReport').textContent='渐进计算中，尚未产生最终运行记录。';$('pltDownload').disabled=true;
}
const warningNames={'low-frequency-asymptotic-approximation':'高频渐近条件不足','surface-grazing-asymptotic-approximation':'接近表面掠射方向','finite-endpoint-neighborhood-not-modeled':'接近物理边端点，端点项未建模','region-truncated-stationary-neighborhood':'驻相邻域受有限区域截断','endpoint-corner-diffraction-not-modeled':'端点或角点项未建模','reflected-shadow-seam-local-approximation':'反射阴影边界采用局部近似','grazing-asymptotic-exclusion':'边缘掠射项已排除'};
function show(result){if(result?.partial===true||result?.progressive&&(result.progressive.completedSamplesPerPixel!==result.options?.samplesPerPixel||result.results?.some(r=>r.partial===true||r.completedSamplesPerPixel!==result.options.samplesPerPixel||r.minSamplesPerPixel!==result.options.samplesPerPixel||r.maxSamplesPerPixel!==result.options.samplesPerPixel||r.sampleCounts?.length!==r.width*r.height||r.sampleCounts.some(n=>n!==result.options.samplesPerPixel))))throw new Error('未完成的样本不能标记为最终结果');if(!Array.isArray(result?.results)||result.results.length!==2||result.results.filter(r=>r.wave===true).length!==1||result.results.filter(r=>r.wave===false).length!==1||result.results.some(r=>!Number.isInteger(r.width)||!Number.isInteger(r.height)||r.width!==result.options?.width||r.height!==result.options?.height||r.image?.length!==r.width*r.height||!Array.from(r.image).every(v=>Number.isFinite(v)&&v>=0)))throw new Error('相机结果缺失、尺寸不符或含无效数值');if(activeRequest&&(result.options.spectralMode??'monochrome')!==(activeRequest.options.spectralMode??'monochrome'))throw new Error('结果光谱模式与当前请求不符');for(const r of result.results)validateXYZ(r,result.options.spectralMode==='visible');lastResult=result;lastPreview=null;for(const r of result.results)$(r.wave?'pltWaveSamples':'pltRaySamples').textContent=`${result.options.samplesPerPixel} spp · 已完成`;paint();const w=result.results.find(r=>r.wave);$('pltBackend').textContent=w.backend;$('pltGeometry').textContent=`${result.scene.triangles} / ${result.scene.wedges}`;$('pltEvents').textContent=w.events.toLocaleString();$('pltMulti').textContent=w.stats.twoDiffractingPaths.toLocaleString();$('pltParity').textContent=result.results.some(r=>r.validation&&!r.validation.passed)?'CPU 回退':result.results.every(r=>r.validation?.passed)?'全部通过':result.results.some(r=>r.validation?.passed)?'部分 GPU 通过':'CPU';$('pltMeasurement').textContent=`相对 PLT 相机响应均值 ${w.measurement.mean.toPrecision(4)}。每像素 ${result.options.samplesPerPixel} 样本；实际最多 ${w.stats.maxDiffractingPerPath} 个 UTD 区域、${w.stats.maxSurfacePerPath} 次表面交互。当前样本含 ${w.stats.twoDiffractingContributions} 项双区域到光源贡献。`;$('pltWarnings').textContent=[...result.warnings,...(result.scene.unsupportedEdges?[`${result.scene.unsupportedEdges} 条局部几何边不满足本版 UTD 条件；仍参与遮挡与表面散射。`]:[]),...Object.entries(w.stats.approximationWarnings??{}).map(([key,n])=>`${warningNames[key]??key}：${n} 个局部算子`),'UTD 高阶、角点与端点项未完整建模；跨区域相干性采用论文局部化近似。原生 Keller 角采样不构成严格的全场立体角能量标定。低样本图像可能有明显噪声。'].join('\n');if(result.options.spectralMode==='visible'){$('pltMeasurement').textContent+=` 光谱范围 360–830 nm；当前光源 ${result.options.spectralSource}，模型表面 ${result.options.spectralMaterial}。`;$('pltWarnings').textContent+='\n颜色仅标定到 CIE 观察者；原生传输量仍是相对响应。XYZ 转换可能得到负的线性 sRGB（超出显示色域），只在显示时裁为 0；固定指数压缩与标准 sRGB 传递函数不会改写原始 XYZ。方差是相关光谱样本的描述统计，不是置信区间。';}
const report={scope:result.scope,colorimetry:result.colorimetry,options:result.options,camera:result.camera,scene:result.scene,totalMs:result.totalMs,progressive:result.progressive,comparison:result.comparison,results:result.results.map(({image,xyz,sampleCounts,...rest})=>rest)};$('pltReport').textContent=JSON.stringify(report,null,2);$('pltDownload').disabled=false;status(`计算完成 · ${(result.totalMs/1000).toFixed(1)} 秒${result.progressive?.firstFullPassMs!==undefined?` · 首轮完整预览 ${(result.progressive.firstFullPassMs/1000).toFixed(1)} 秒`:''} · 同一曝光比较。`);}
$('pltRun').addEventListener('click',()=>{stop();clearResult();const id=generation;busy=true;$('pltRun').disabled=true;$('pltCancel').hidden=false;$('pltProgress').hidden=false;$('pltProgress').value=0;status('正在本地构建三角形 BVH 与相机路径…');try{worker=new Worker(new URL('./plt-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.id!==generation)return;if(data.type==='progress'){status(data.text);$('pltProgress').value=data.fraction;}else if(data.type==='preview'){try{showPreview(data.preview??data);}catch(error){stop();clearResult();status(`渐进帧被拒绝：${error.message}`);}}else if(data.type==='result'){stop();try{show(data.result);}catch(error){clearResult();status(`结果被拒绝：${error.message}`);}}else if(data.type==='error'){stop();clearResult();status(`未生成图像：${data.error}`);}};worker.onerror=e=>{if(id!==generation)return;stop();clearResult();status(`计算 Worker 出错：${e.message||'无法初始化'}`);};worker.onmessageerror=()=>{if(id!==generation)return;stop();clearResult();status('计算 Worker 的结果无法读取，未显示图像。');};activeRequest=request();worker.postMessage(activeRequest);}catch(error){stop();status(`无法启动：${error.message}`);}});
$('pltCancel').addEventListener('click',()=>{stop();clearResult();status('已取消。没有保留未完成的图像。');});
for(const id of ids)$(id).addEventListener('input',invalidate);
$('pltExposure').addEventListener('input',()=>{$('pltExposureValue').textContent=`${$('pltExposure').value} EV`;paint();});
$('pltFile').addEventListener('change',async()=>{const file=$('pltFile').files?.[0];if(!file)return;invalidate();const id=generation;if(file.size>2*1024*1024){status('OBJ 超过 2 MiB 限制。');return;}try{const text=await file.text();if(id!==generation)return;const {parseOBJ}=await import('./mesh-geometry.js');parseOBJ(text);if(id!==generation)return;objText=text;objName=file.name;$('pltFileName').textContent=`${objName} · 仅保存在本地内存`;$('pltClearModel').disabled=false;status('OBJ 已在本地载入。计算时将参与遮挡、表面散射与可用边缘衍射。');}catch(error){if(id===generation)status(`OBJ 未载入：${error.message}`);}});
$('pltClearModel').addEventListener('click',()=>{objText=null;objName=null;$('pltFile').value='';$('pltFileName').textContent='仅在浏览器内读取，模型不会上传';$('pltClearModel').disabled=true;invalidate();});
$('pltReset').addEventListener('click',()=>{for(const [id,value] of Object.entries({pltPreset:'gallery',pltModelYaw:'0',pltScale:'1',pltMaterial:'0',pltYaw:'0',pltPitch:'0',pltWavelength:'.025',pltDepth:'4',pltResolution:'48',pltSamples:'16',pltCompute:'auto',pltExposure:'0',pltSpectrum:'monochrome',pltSource:'D65',pltSourcePower:'5',pltSpectralMaterial:'red'}))$(id).value=value;objText=null;objName=null;$('pltFile').value='';$('pltFileName').textContent='仅在浏览器内读取，模型不会上传';$('pltClearModel').disabled=true;$('pltExposureValue').textContent='0 EV';invalidate();status('已恢复默认场景、模型与相机。');});
$('pltDownload').addEventListener('click',()=>{if(!lastResult)return;const blob=new Blob([$('pltReport').textContent],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wave-tracing-local-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
window.addEventListener('pagehide',stop);

$('pltVisiblePreset').addEventListener('click',()=>{for(const [id,value]of Object.entries({pltPreset:'micro-gallery',pltSpectrum:'visible',pltSource:'D65',pltSpectralMaterial:'red',pltMaterial:'0',pltScale:'1',pltResolution:'48',pltSamples:'64',pltDepth:'4',pltYaw:'0',pltPitch:'0'}))$(id).value=value;invalidate();status('可见光微型场景已准备好。点击计算；颜色由逐波长传输产生，仍需累积样本。');});
spectralControls();
